function parseUrl(str){
  var s=str;
  var pi=s.indexOf('://');
  if(pi!==-1) s=s.substring(pi+3);
  var hi=s.indexOf('#');
  if(hi!==-1) s=s.substring(0,hi);
  var search='';
  var qi=s.indexOf('?');
  if(qi!==-1){search=s.substring(qi+1);s=s.substring(0,qi);}
  var hostname='';var pathname='/';
  var si=s.indexOf('/');
  if(si!==-1){hostname=s.substring(0,si).toLowerCase();pathname=s.substring(si);}
  else{hostname=s.toLowerCase();}
  function getParam(name){
    if(!search) return null;
    var pairs=search.split('&');
    for(var i=0;i<pairs.length;i++){
      var eq=pairs[i].indexOf('=');
      if(eq!==-1&&pairs[i].substring(0,eq)===name) return pairs[i].substring(eq+1);
      else if(pairs[i]===name) return "";
    }
    return null;
  }
  return {hostname:hostname,pathname:pathname,search:search,getParam:getParam};
}
function normalizeFb(raw){
  var fb=(raw||'').trim();
  if(!fb) return {action:'skip',reason:'empty'};
  if(fb.charAt(0)==='@') fb=fb.substring(1).trim();
  if(!fb) return {action:'skip',reason:'empty_after_trim'};

  var lo=fb.toLowerCase();
  var hasDomain=lo.indexOf('facebook.com')!==-1||lo.indexOf('fb.com')!==-1||
    lo.indexOf('fb.me')!==-1||lo.indexOf('fb.watch')!==-1||
    lo.indexOf('m.me')!==-1||lo.indexOf('messenger.com')!==-1;

  if(!hasDomain){
    var ok=true;
    for(var i=0;i<fb.length;i++){
      var c=fb.charAt(i);
      if(!((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c==='.'||c==='-'||c==='_')){ok=false;break;}
    }
    if(ok&&fb.length>0) return {action:'clean',url:'https://www.facebook.com/'+fb};
    return {action:'skip',reason:'no_domain_invalid_chars'};
  }

  if(!lo.startsWith('http://')&&!lo.startsWith('https://')) fb='https://'+fb;

  var u=parseUrl(fb);
  var host=u.hostname;
  var path=u.pathname;

  if(host==='m.me'||host==='www.m.me'){
    var un=path;
    while(un.charAt(0)==='/') un=un.substring(1);
    while(un.length>0&&un.charAt(un.length-1)==='/') un=un.substring(0,un.length-1);
    return un?{action:'clean',url:'https://www.facebook.com/'+un}:{action:'skip',reason:'empty_mme'};
  }

  if(host.indexOf('messenger.com')!==-1){
    var ti=path.indexOf('/t/');
    if(ti!==-1){
      var after=path.substring(ti+3);
      var si2=after.indexOf('/');
      var thread=si2!==-1?after.substring(0,si2):after;
      if(thread) return {action:'clean',url:'https://www.facebook.com/'+thread};
    }
    return {action:'skip',reason:'no_messenger_thread'};
  }

  if(host==='fb.watch'||host==='fb.me') return {action:'fetch',url:fb};

  var pathLo=path.toLowerCase();
  if(pathLo.indexOf('/share/')!==-1||pathLo==='/share') return {action:'fetch',url:fb};
  if(host==='l.facebook.com'||host==='lm.facebook.com') return {action:'fetch',url:fb};
  if(pathLo.indexOf('/story.php')!==-1) return {action:'fetch',url:fb};

  if(pathLo.indexOf('/profile.php')!==-1){
    var pid=u.getParam('id');
    return pid?{action:'fetch',url:'https://www.facebook.com/profile.php?id='+pid}:{action:'skip',reason:'no_profile_id'};
  }

  if(pathLo.indexOf('/people/')!==-1&&pathLo.indexOf('pfbid')!==-1){
    var cp=path;
    while(cp.length>0&&cp.charAt(cp.length-1)==='/') cp=cp.substring(0,cp.length-1);
    return {action:'clean',url:'https://www.facebook.com'+cp};
  }

  if(path.length>1&&path.substring(0,6).toLowerCase()==='/pfbid'){
    var cp2=path;
    while(cp2.length>0&&cp2.charAt(cp2.length-1)==='/') cp2=cp2.substring(0,cp2.length-1);
    return {action:'clean',url:'https://www.facebook.com'+cp2};
  }

  var rawPath=path;
  while(rawPath.charAt(0)==='/') rawPath=rawPath.substring(1);
  while(rawPath.length>0&&rawPath.charAt(rawPath.length-1)==='/') rawPath=rawPath.substring(0,rawPath.length-1);
  var seg=rawPath.split('/').filter(function(s){return s.length>0;});

  if(seg.length===0) return {action:'skip',reason:'no_path'};

  if(seg.length===1&&seg[0].toLowerCase().indexOf('.php')===-1){
    return {action:'clean',url:'https://www.facebook.com/'+seg[0]};
  }

  if(seg.length>=2){
    var first=seg[0];
    var firstLo=first.toLowerCase();
    var nonProfile='groups,events,watch,gaming,marketplace,pages,hashtag,search,help,settings,login,recover,dialog,sharer,plugins,ads,business,privacy,policies,legal,directory,biz,fundraisers,offers,jobs';
    if(nonProfile.split(',').indexOf(firstLo)!==-1) return {action:'skip',reason:'non_profile_path'};
    if(firstLo.indexOf('.php')!==-1) return {action:'skip',reason:'php_endpoint'};
    var profileSubs='posts,photos,videos,about,friends,reviews,reels,followers,following,likes,photos_albums,map,sports,music,movies,tv,books,check_ins,mentions,timeline,info';
    var sec=seg[1].toLowerCase();
    if(profileSubs.split(',').indexOf(sec)!==-1) return {action:'clean',url:'https://www.facebook.com/'+first};
    var isNum=sec.length>0;
    for(var j=0;j<sec.length;j++){if(sec.charAt(j)<'0'||sec.charAt(j)>'9'){isNum=false;break;}}
    if(isNum) return {action:'clean',url:'https://www.facebook.com/'+first};
    var validFirst=first.length>=2;
    for(var k=0;k<first.length&&validFirst;k++){
      var ch=first.charAt(k);
      if(!((ch>='a'&&ch<='z')||(ch>='A'&&ch<='Z')||(ch>='0'&&ch<='9')||ch==='.'||ch==='-'||ch==='_')) validFirst=false;
    }
    if(validFirst) return {action:'clean',url:'https://www.facebook.com/'+first};
  }

  return {action:'skip',reason:'unrecognized_pattern'};
}
var res=$input.first().json;
if(res.statusCode&&res.statusCode!==200){
  return [{json:{error:"DB fetch failed",statusCode:res.statusCode,body:JSON.stringify(res.body).substring(0,500)}}];
}
var rows;
if(Array.isArray(res.body)) rows=res.body;
else if(typeof res.body==='string'){try{rows=JSON.parse(res.body);}catch(e){rows=[];}}
else if(Array.isArray(res)) rows=res;
else rows=[];
if(!Array.isArray(rows)) rows=[];
if(rows.length===0) return [{json:{info:"no_rows",rowCount:0}}];
var out=[];
var skippedCount=0;
var alreadyCleanCount=0;
var skippedSamples=[];
var alreadyCleanSamples=[];
for(var i=0;i<rows.length;i++){
  var r=rows[i];
  var fb=(r.facebook||'').trim();
  var n=normalizeFb(fb);
  if(n.action==='fetch'){
    out.push({json:{id:r.id,short_url:n.url,action:'fetch'}});
  }else if(n.action==='clean'){
    if(n.url&&n.url!==fb){
      out.push({json:{id:r.id,cleaned:n.url,action:'clean'}});
    }else{
      alreadyCleanCount++;
      if(alreadyCleanSamples.length<10) alreadyCleanSamples.push({id:r.id,facebook:fb,cleanedUrl:n.url});
    }
  }else{
    skippedCount++;
    if(skippedSamples.length<10) skippedSamples.push({id:r.id,facebook:fb,reason:n.reason});
  }
}
if(out.length===0){
  return [{json:{
    info:"all_skipped_or_already_clean",
    total:rows.length,
    skipped:skippedCount,
    already_clean:alreadyCleanCount,
    skipped_samples:skippedSamples,
    already_clean_samples:alreadyCleanSamples,
    raw_sample:rows.slice(0,5).map(function(r){return {id:r.id,facebook:r.facebook};})
  }}];
}
return out;

