var src=$('Loop Over Items').item.json;
var id=src.id;
var headers=$json.headers||{};
var finalUrl=headers.location||headers.Location||'';
if(!finalUrl){
  var body=typeof $json.body==='string'?$json.body:JSON.stringify($json.body||'');
  var idx=body.indexOf('canonical');
  if(idx===-1) idx=body.indexOf('og:url');
  if(idx!==-1){
    var hrefIdx=body.indexOf('href=',idx);
    if(hrefIdx===-1) hrefIdx=body.indexOf('content=',idx);
    if(hrefIdx!==-1){
      var qStart=hrefIdx+5;
      while(qStart<body.length&&body.charAt(qStart)!=="'"&&body.charAt(qStart)!=='"') qStart++;
      var qChar=body.charAt(qStart);
      var start=qStart+1;
      var end=body.indexOf(qChar,start);
      if(end!==-1) finalUrl=body.substring(start,end);
    }
  }
}
while(finalUrl.indexOf('&amp;')!==-1){
  var ai=finalUrl.indexOf('&amp;');
  finalUrl=finalUrl.substring(0,ai)+'&'+finalUrl.substring(ai+5);
}
var status='ok';
var cleaned='';
if(!finalUrl){
  status='no_redirect';
}else if(finalUrl.indexOf('/login')!==-1||finalUrl.indexOf('checkpoint')!==-1){
  status='login_wall';
}else{
  var n=normalizeFb(finalUrl);
  if(n.action==='clean') cleaned=n.url;
  else{
    var qi2=finalUrl.indexOf('?');
    var hi2=finalUrl.indexOf('#');
    if(qi2!==-1) cleaned=finalUrl.substring(0,qi2);
    else if(hi2!==-1) cleaned=finalUrl.substring(0,hi2);
    else cleaned=finalUrl;
  }
}
return {json:{id:id,cleaned:cleaned,status:status,resolved:status==='ok'&&cleaned.length>0}};
